-- Replace PROJECT_ID. Views are not tenant-scoped: BI tools must filter organization_id/workspace_id

-- (or sit behind row access policies / authorized views).

CREATE OR REPLACE VIEW `PROJECT_ID.conversation_analytics.latest_analysis_runs` AS
SELECT * EXCEPT(rn) FROM (
 SELECT r.*, ROW_NUMBER() OVER (PARTITION BY organization_id, workspace_id, run_id ORDER BY created_at DESC) AS rn
 FROM `PROJECT_ID.conversation_analytics.analysis_runs` r
) WHERE rn = 1;

CREATE OR REPLACE VIEW `PROJECT_ID.conversation_analytics.current_session_results` AS
SELECT * EXCEPT(rn) FROM (
 SELECT a.*, ROW_NUMBER() OVER (
 PARTITION BY organization_id, workspace_id, session_id, rubric_id
 ORDER BY rubric_version DESC, completed_at DESC, analysis_id DESC
 ) AS rn
 FROM `PROJECT_ID.conversation_analytics.latest_session_analyses` a
) WHERE rn = 1;

CREATE OR REPLACE VIEW `PROJECT_ID.conversation_analytics.latest_criterion_results` AS
SELECT
 c.analysis_id, c.organization_id, c.workspace_id, c.session_id, a.rubric_id, a.rubric_version, c.criterion_id,
 c.criterion_weight, c.normalized_score, c.weighted_score, c.applicability_status, c.confidence,
 c.evidence_message_ids, c.evaluated_at
FROM `PROJECT_ID.conversation_analytics.session_criterion_results` c
JOIN `PROJECT_ID.conversation_analytics.latest_session_analyses` a
 ON a.analysis_id = c.analysis_id AND a.organization_id = c.organization_id AND a.workspace_id = c.workspace_id
QUALIFY ROW_NUMBER() OVER (PARTITION BY c.analysis_id, c.criterion_id ORDER BY c.evaluated_at DESC) = 1;

CREATE OR REPLACE VIEW `PROJECT_ID.conversation_analytics.gold_cost_daily` AS
SELECT
 organization_id, workspace_id, DATE(started_at) AS day, analysis_mode, model,
 COUNT(DISTINCT analysis_id) AS analyses,
 SUM(estimated_cost_usd) AS cost_usd,
 AVG(processing_duration_ms) AS avg_duration_ms
FROM `PROJECT_ID.conversation_analytics.session_analyses`
GROUP BY organization_id, workspace_id, day, analysis_mode, model;

CREATE OR REPLACE VIEW `PROJECT_ID.conversation_analytics.gold_daily_quality` AS
SELECT
 organization_id, workspace_id, rubric_id, rubric_version, DATE(completed_at) AS day,
 COUNT(*) AS sessions,
 COUNTIF(overall_score IS NOT NULL) AS scored_sessions,
 AVG(overall_score) AS avg_score,
 COUNTIF(approval_status = 'APPROVED') AS approved,
 COUNTIF(approval_status = 'REJECTED') AS rejected,
 COUNTIF(analysis_status = 'NEEDS_REVIEW') AS needs_review,
 COUNTIF(analysis_status = 'NOT_EVALUABLE') AS not_evaluable,
 SAFE_DIVIDE(COUNTIF(approval_status = 'APPROVED'), COUNTIF(overall_score IS NOT NULL)) AS approval_rate
FROM `PROJECT_ID.conversation_analytics.current_session_results`
GROUP BY organization_id, workspace_id, rubric_id, rubric_version, day;

CREATE OR REPLACE VIEW `PROJECT_ID.conversation_analytics.gold_criterion_daily` AS
SELECT
 organization_id, workspace_id, rubric_id, rubric_version, criterion_id, DATE(evaluated_at) AS day,
 COUNT(*) AS evaluations,
 COUNTIF(applicability_status = 'APPLICABLE') AS applicable,
 COUNTIF(applicability_status = 'NOT_APPLICABLE') AS not_applicable,
 COUNTIF(applicability_status = 'INSUFFICIENT_EVIDENCE') AS insufficient_evidence,
 AVG(IF(applicability_status = 'APPLICABLE', normalized_score, NULL)) AS avg_normalized_score,
 SAFE_DIVIDE(COUNTIF(applicability_status = 'INSUFFICIENT_EVIDENCE'), COUNT(*)) AS insufficient_rate
FROM `PROJECT_ID.conversation_analytics.latest_criterion_results`
GROUP BY organization_id, workspace_id, rubric_id, rubric_version, criterion_id, day;

CREATE OR REPLACE VIEW `PROJECT_ID.conversation_analytics.gold_run_health` AS
SELECT
 organization_id, workspace_id, DATE(created_at) AS day, processing_mode, run_status,
 COUNT(*) AS runs,
 SUM(sessions_processed) AS sessions_processed,
 SUM(sessions_failed) AS sessions_failed,
 SUM(sessions_skipped) AS sessions_skipped,
 SUM(actual_cost_usd) AS actual_cost_usd
FROM `PROJECT_ID.conversation_analytics.latest_analysis_runs`
GROUP BY organization_id, workspace_id, day, processing_mode, run_status;

CREATE OR REPLACE VIEW `PROJECT_ID.conversation_analytics.review_queue` AS
SELECT organization_id, workspace_id, session_id, rubric_id, rubric_version, analysis_id, completed_at
FROM `PROJECT_ID.conversation_analytics.current_session_results`
WHERE analysis_status = 'NEEDS_REVIEW';
